/* Messages-style private visitor conversations, backed by the email chat server. */
(() => {
views.messages={title:'Messages',status:'A direct conversation with Princewill',keywords:'message imessage email chat contact enquiry reply',render:()=>'<button class="btn" data-open="messages">Open Messages →</button>'};
const dock=document.createElement('button');dock.className='dock-icon macos-app dock-messages';dock.dataset.open='messages';dock.setAttribute('aria-label','Messages — chat with Princewill');dock.innerHTML='<img class="macos-app-image" src="assets/tahoe/messages.svg" alt="" draggable="false"><small>Messages</small>';document.querySelector('.dock-mail').before(dock);dockIcons.push(dock);
const shell=document.createElement('dialog');shell.id='portfolio-messages';shell.className='portfolio-messages';shell.setAttribute('aria-labelledby','messages-title');shell.innerHTML=`<header class="messages-bar"><div class="safari-lights"><button id="messages-close" aria-label="Close Messages"></button><button id="messages-minimise" aria-label="Minimise Messages"></button><button id="messages-maximise" aria-label="Maximise Messages"></button></div><strong id="messages-title">Messages</strong></header><div class="messages-layout"><aside><span>CONVERSATIONS</span><div class="messages-person"><img src="assets/princewill-linkedin.jpg" alt=""><div><strong>Princewill Okube</strong><small>Your private conversation</small></div></div><p>Your conversation stays in this browser. Replies arrive here while the chat is open.</p></aside><section class="messages-conversation"><header><img src="assets/princewill-linkedin.jpg" alt="Princewill"><div><strong>Princewill Okube</strong><small id="messages-connection">Connecting…</small></div></header><div id="messages-log" role="log" aria-label="Conversation with Princewill" aria-live="polite"><p class="messages-greeting">A good idea starts with a hello.<br>Tell me what you have in mind.</p></div><form id="messages-form"><div id="messages-identity"><label>Your name<input name="name" autocomplete="name" maxlength="100" required placeholder="Name or brand"></label><label>Your email<input name="email" autocomplete="email" type="email" maxlength="254" required placeholder="you@example.com"></label></div><label class="messages-honeypot" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><label class="sr-only" for="messages-text">Your message</label><div class="messages-compose"><textarea id="messages-text" name="text" maxlength="3000" rows="2" required placeholder="Message Princewill…"></textarea><button id="messages-send" type="submit" aria-label="Send message" disabled>↑</button></div><p id="messages-feedback" role="status">Checking email delivery…</p><div class="messages-direct-contact"><a href="mailto:okubep@gmail.com">Email Princewill ↗</a><a href="https://www.linkedin.com/in/princewillokube/" target="_blank" rel="noopener noreferrer">Message on LinkedIn ↗</a></div><small class="messages-privacy">Messages are stored to let Princewill reply. Your email is shared with him. No automated replies.</small></form></section></div>`;document.querySelector('#desktop').append(shell);
const $=s=>shell.querySelector(s),form=$('#messages-form'),log=$('#messages-log'),feedback=$('#messages-feedback');let configured=false,sending=false,timer=0,lastMessages='',clientId=null,lastText='',lastFocus=null,firstSync=true;const seenReplies=new Set();
async function api(path,options={}){const r=await fetch('/api/chat/'+path,{credentials:'same-origin',...options});const data=await r.json();if(!r.ok)throw Error(data.error||'The chat service is unavailable.');return data}
function show(data){for(const m of data.messages){if(m.role==='princewill'&&!seenReplies.has(m.id)){if(!firstSync)window.dispatchEvent(new CustomEvent('portfolio:notification',{detail:{title:'New reply from Princewill',body:'You have a new reply in Messages.',action:'messages'}}));seenReplies.add(m.id)}}firstSync=false;if(data.chat){$('#messages-identity').hidden=true;form.elements.name.required=form.elements.email.required=false}const key=JSON.stringify(data.messages);if(key===lastMessages)return;lastMessages=key;if(!data.messages.length)return;log.replaceChildren();for(const m of data.messages){const row=document.createElement('div');row.className='messages-row '+(m.role==='visitor'?'outgoing':'incoming');const bubble=document.createElement('p');bubble.textContent=m.text;const label=document.createElement('small');label.textContent=(m.role==='princewill'?'Princewill · ':'You · ')+new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit'}).format(new Date(m.created))+(m.role==='visitor'?' · '+(m.status==='sent'?'Sent to email service':m.status==='failed'?'Not sent · retry available':'Sending…'):'');row.append(bubble,label);log.append(row)}log.scrollTop=log.scrollHeight}
async function refresh(){if(!shell.open||document.hidden)return;try{show(await api('messages'))}catch{feedback.textContent='Connection interrupted. Your draft is still here.'}}
async function connect(){try{const config=await api('config');configured=config.ready;$('#messages-connection').textContent=configured?'Email connected · replies return here':'Email connection being prepared';feedback.textContent=configured?'Send a message. Princewill can reply here from his email.':'Email chat setup is in progress. Messages cannot be sent yet.';$('#messages-send').disabled=!configured;await refresh()}catch{$('#messages-connection').textContent='Chat server unavailable';feedback.textContent='Website chat is unavailable. Please use the email or LinkedIn link below.'}}
window.openMessages=()=>{lastFocus=document.activeElement;if(!shell.open)shell.show();shell.style.zIndex='65';dock.classList.add('is-running');window.MacDesktopMotion?.open(shell,dock);connect();clearInterval(timer);timer=setInterval(refresh,8000);$('#messages-text').focus()};
function close(minimise=false){clearInterval(timer);const done=()=>{shell.close();dock.classList.remove('is-running');dock.classList.toggle('is-minimised',minimise);lastFocus?.focus()};if(window.MacDesktopMotion)window.MacDesktopMotion.close(shell,dock,minimise,done);else done()}
$('#messages-close').onclick=()=>close();$('#messages-minimise').onclick=()=>close(true);$('#messages-maximise').onclick=()=>shell.classList.toggle('messages-maximised');shell.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close()}if((e.metaKey||e.ctrlKey)&&e.key==='Enter')form.requestSubmit()});shell.addEventListener('cancel',e=>{e.preventDefault();close()});document.querySelector('#lock-button').addEventListener('click',()=>{if(shell.open)close()});
form.addEventListener('submit',async e=>{e.preventDefault();if(!configured||sending)return;const text=$('#messages-text').value.trim();if(!text)return;if(!clientId||lastText!==text){clientId=crypto.randomUUID();lastText=text}sending=true;$('#messages-send').disabled=true;feedback.textContent='Sending…';try{const data=await api('messages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,clientId,name:form.elements.name.value,email:form.elements.email.value,website:form.elements.website.value})});show(data);$('#messages-text').value='';clientId=null;feedback.textContent='Accepted by the email service. Princewill’s reply will appear here.'}catch(err){feedback.textContent=err.message;await refresh()}finally{sending=false;$('#messages-send').disabled=!configured}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&shell.open)refresh()});window.addEventListener('pagehide',()=>clearInterval(timer));
})();
